//! Inference-only incremental KV cache for MSA (block-sparse attention,
//! MiniMax MSA arXiv 2606.13392).
//!
//! Incremental generation forwards one byte at a time; without a cache the
//! block-sparse arm sees only that byte (`k > 1` gate in the loop even turns
//! it off entirely), so generated bytes never participate in MSA attention.
//! [`MsaCache`] keeps, per loop iteration, the projected K/K_idx/V streams of
//! every token processed so far and gives each new token the same top-k
//! blockwise attention over the full history as the batched training path:
//!
//! 1. project the new token once (index q/k, main q/k/v),
//! 2. append K/K_idx/V to that iteration's streams,
//! 3. score the query against cached index blocks (block max, optional
//!    local-block bias), pick the top-k blocks,
//! 4. run [`sparse_attn_batched_gqa`] — the training kernel — over the
//!    selected blocks of the cached K/V.
//!
//! Equivalence with the batched causal path holds up to float reduction
//! order: at absolute position t the visible key set is exactly `{<= t}` on
//! both paths, including the partial-last-block tail clamp semantics.
//! Rope is not supported (aria runs the MSA arm without rope).

use burn::tensor::ops::PadMode;
use burn::tensor::{Int, Tensor};

use crate::attention::block_scores;
use crate::config::MsaConfig;
use crate::module::MsaModule;
use crate::NEG_INF_SAFE;

/// Per-iteration K/V history: everything processed so far at one loop depth.
#[derive(Debug)]
struct IterStream {
    /// Index-branch keys `[1, 1, S, d_idx]`.
    k_idx: Tensor<4>,
    /// Main keys `[1, Hkv, S, d_head]`.
    k: Tensor<4>,
    /// Main values `[1, Hkv, S, d_head]`.
    v: Tensor<4>,
    len: usize,
}

/// Incremental block-sparse KV cache, one stream per loop iteration.
///
/// The loop shares one MSA module across depth; each depth sees a different
/// hidden stream, so histories are keyed by iteration index exactly as the
/// batched path computes them.
#[derive(Debug)]
pub struct MsaCache {
    cfg: MsaConfig,
    iters: Vec<Option<IterStream>>,
}

impl MsaCache {
    pub fn new(cfg: MsaConfig) -> Self {
        assert!(!cfg.use_rope, "MsaCache does not shift rope positions");
        assert!(cfg.causal, "MsaCache implements causal generation");
        Self {
            cfg,
            iters: Vec::new(),
        }
    }

    /// Clear and size the cache for `n_iters` loop iterations. Streams are
    /// allocated lazily on the first pushed token (device comes from it).
    pub fn reset(&mut self, n_iters: usize) {
        self.iters = (0..n_iters).map(|_| None).collect();
    }

    /// Recorded stream lengths (for [`rollback`](Self::rollback)).
    pub fn mark(&self) -> Vec<usize> {
        self.iters
            .iter()
            .map(|s| s.as_ref().map_or(0, |s| s.len))
            .collect()
    }

    /// Truncate every stream back to its recorded length, dropping everything
    /// pushed after [`mark`](Self::mark). Used around speculative drafts whose
    /// tokens get re-forwarded by the verifying pass.
    pub fn rollback(&mut self, mark: &[usize]) {
        assert_eq!(mark.len(), self.iters.len(), "stale mark length");
        for (stream, &len) in self.iters.iter_mut().zip(mark) {
            match (stream.as_mut(), len) {
                (None, 0) => {}
                (None, _) => panic!("mark references a stream never created"),
                (Some(_), 0) => *stream = None,
                (Some(s), _) if s.len > len => s.truncate(len),
                (Some(_), _) => {}
            }
        }
    }

    /// Cached-history length for one iteration (test/diagnostic).
    pub fn stream_len(&self, iter: usize) -> usize {
        self.iters[iter].as_ref().map_or(0, |s| s.len)
    }

    /// Run the cached MSA arm for a whole segment `x [b, m, d_model]` at loop
    /// iteration `iter`: each token is pushed and then attends the full
    /// history (itself included), sequentially, in segment order. Returns the
    /// out-projected MSA output `[b, m, d_model]`.
    ///
    /// Batch must be 1 (generation). Under MoR routing the segment rows are
    /// the active pool in router order — still a valid causal order for the
    /// cache, though not necessarily byte order within the round.
    pub fn step(&mut self, msa: &MsaModule, x: Tensor<3>, iter: usize) -> Tensor<3> {
        let [batch, seg, dm] = x.dims();
        assert_eq!(batch, 1, "cached MSA arm supports batch 1");
        assert!(
            iter < self.iters.len(),
            "iteration {iter} outside cache (reset with loop depth)"
        );
        let cfg = self.cfg.clone();
        let mut outs = Vec::with_capacity(seg);
        for j in 0..seg {
            let xj = x.clone().slice([0..1, j..j + 1, 0..dm]); // [1,1,d]
                                                               // Head split follows IndexBranch/SparseAttention: group as
                                                               // [b, s, h, d] then swap to [b, h, s, d].
            let q_idx = msa
                .index_branch
                .q_proj
                .forward(xj.clone())
                .reshape([1, 1, cfg.n_heads_kv, cfg.d_idx])
                .swap_dims(1, 2);
            let q_main = msa
                .attention
                .q_proj
                .forward(xj.clone())
                .reshape([1, 1, cfg.n_heads_q, cfg.d_head])
                .swap_dims(1, 2);
            let k_new = msa
                .attention
                .k_proj
                .forward(xj.clone())
                .reshape([1, 1, cfg.n_heads_kv, cfg.d_head])
                .swap_dims(1, 2);
            let v_new = msa
                .attention
                .v_proj
                .forward(xj.clone())
                .reshape([1, 1, cfg.n_heads_kv, cfg.d_head])
                .swap_dims(1, 2);
            let kidx_new = msa.index_branch.k_proj.forward(xj);
            let stream = self.iters[iter].get_or_insert_with(|| IterStream {
                k_idx: Tensor::zeros([1, 1, 0, cfg.d_idx], &x.device()),
                k: Tensor::zeros([1, cfg.n_heads_kv, 0, cfg.d_head], &x.device()),
                v: Tensor::zeros([1, cfg.n_heads_kv, 0, cfg.d_head], &x.device()),
                len: 0,
            });
            stream.push(
                k_new.reshape([1, cfg.n_heads_kv, 1, cfg.d_head]),
                v_new.reshape([1, cfg.n_heads_kv, 1, cfg.d_head]),
                kidx_new.reshape([1, 1, 1, cfg.d_idx]),
            );
            outs.push(stream.attend(q_main, q_idx, &msa.attention.out_proj, &cfg));
        }
        Tensor::cat(outs, 1) // [1, seg, d_model]
    }
}

impl IterStream {
    fn push(&mut self, k: Tensor<4>, v: Tensor<4>, k_idx: Tensor<4>) {
        self.k = Tensor::cat(vec![self.k.clone(), k], 2);
        self.v = Tensor::cat(vec![self.v.clone(), v], 2);
        self.k_idx = Tensor::cat(vec![self.k_idx.clone(), k_idx], 2);
        self.len += 1;
    }

    fn truncate(&mut self, len: usize) {
        let [_, hkv, _, dh] = self.k.dims();
        let di = self.k_idx.dims()[3];
        // Rollback runs once per speculative round — clones are fine.
        self.k = self.k.clone().slice([0..1, 0..hkv, 0..len, 0..dh]);
        self.v = self.v.clone().slice([0..1, 0..hkv, 0..len, 0..dh]);
        self.k_idx = self.k_idx.clone().slice([0..1, 0..1, 0..len, 0..di]);
        self.len = len;
    }

    /// Top-k blockwise attention of one query (already pushed, absolute
    /// position `len - 1`) against the full stream.
    fn attend(
        &self,
        q: Tensor<4>,
        q_idx: Tensor<4>,
        out_proj: &burn::nn::Linear,
        cfg: &MsaConfig,
    ) -> Tensor<3> {
        let seq = self.len;
        let n_blocks = seq.div_ceil(cfg.block_size);
        let padded = n_blocks * cfg.block_size;
        let scale = (cfg.d_idx as f64).sqrt();

        // Block scores: [1, Hkv, 1, n_blocks]; the partial tail of the last
        // block is padded to -inf so it never wins the block max.
        let scores = q_idx
            .matmul(self.k_idx.clone().swap_dims(2, 3))
            .div_scalar(scale);
        let scores = if padded > seq {
            scores.pad(
                [(0, 0), (0, 0), (0, 0), (0, padded - seq)],
                PadMode::Constant(NEG_INF_SAFE),
            )
        } else {
            scores
        };
        let block_max = scores
            .reshape([1, cfg.n_heads_kv, 1, n_blocks, cfg.block_size])
            .max_dim(4)
            .squeeze_dim::<4>(4);

        // Local-block bias at the query's ABSOLUTE position, mirroring
        // TopKSelector::force_local_block (which is relative to the query
        // window and would bias block 0 here).
        let topk = cfg.topk.min(n_blocks);
        let indices = if topk >= n_blocks {
            Tensor::<1, Int>::arange(0..n_blocks as i64, &q.device())
                .reshape([1, 1, 1, n_blocks])
                .repeat_dim(1, cfg.n_heads_kv)
        } else {
            let mut biased = block_max;
            if cfg.force_local_block && topk > 1 {
                let local = (seq - 1) / cfg.block_size;
                let bias = Tensor::<1, Int>::arange(0..n_blocks as i64, &q.device())
                    .equal_elem(local as i64)
                    .float()
                    .mul_scalar(1e4)
                    .reshape([1, 1, 1, n_blocks]);
                biased = biased + bias;
            }
            // Masked-argmax picks, ties broken toward the lowest block id
            // (same rule as TopKSelector's argtopk fallback).
            let mut parts = Vec::with_capacity(topk);
            for _ in 0..topk {
                let idx = biased.clone().argmax(3).cast(burn::tensor::IntDType::I64); // [1,Hkv,1,1]
                let oh = idx.clone().one_hot::<5>(n_blocks).float().reshape([
                    1,
                    cfg.n_heads_kv,
                    1,
                    n_blocks,
                ]);
                biased = biased.sub(oh.mul_scalar(1e30_f32));
                parts.push(idx);
            }
            Tensor::cat(parts, 3)
        };

        // Training gather/score math per selected block (`block_scores`) plus
        // gqa's online-softmax update for the single query row. Padding slots
        // beyond the real history are masked on their RAW offsets: the query
        // must attend exactly its causal past. (The batched kernel instead
        // clamps padding to the last real token and only masks idx > q_pos,
        // so its FINAL row of a partial trailing block attends itself several
        // times — the cache deliberately gives the clean prefix semantics.)
        let dh = cfg.d_head;
        let qpkv = cfg.n_heads_q / cfg.n_heads_kv;
        let device = q.device();
        let q_s = q.reshape([1, cfg.n_heads_kv, qpkv, 1, dh]).swap_dims(2, 3); // [1, Hkv, seq_q=1, qpkv, d]
        let offsets = Tensor::<1, Int>::arange(0..cfg.block_size as i64, &device).reshape([
            1,
            1,
            1,
            cfg.block_size,
        ]);
        let q_pos = Tensor::<4, Int>::full([1, 1, 1, 1], (seq - 1) as i64, &device);

        let mut m = Tensor::<5>::full([1, cfg.n_heads_kv, qpkv, 1, 1], -3.0e38_f32, &device);
        let mut l = Tensor::<5>::zeros([1, cfg.n_heads_kv, qpkv, 1, 1], &device);
        let mut out = Tensor::<5>::zeros([1, cfg.n_heads_kv, qpkv, 1, dh], &device);
        for blk in 0..topk {
            let (scores_b, _k_b, v_b, _idx) = block_scores(
                &q_s,
                &self.k,
                &self.v,
                &indices,
                &offsets,
                &q_pos,
                blk,
                cfg.block_size,
                seq,
                (dh as f64).sqrt(),
                false,
            );
            let base = indices
                .clone()
                .slice([0..1, 0..cfg.n_heads_kv, 0..1, blk..blk + 1]);
            let raw = base.mul_scalar(cfg.block_size as i64).add(offsets.clone());
            let scores_b = scores_b.add(
                raw.unsqueeze_dim::<5>(3)
                    .greater_scalar((seq - 1) as i64)
                    .float()
                    .mul_scalar(NEG_INF_SAFE),
            );

            let m_new = m.clone().max_pair(scores_b.clone().max_dim(4));
            let alpha = m.sub(m_new.clone()).exp();
            let e_b = scores_b.sub(m_new.clone()).exp();
            let e_sum = e_b.clone().sum_dim(4);
            out = out
                .mul(alpha.clone())
                .add(e_b.swap_dims(2, 3).matmul(v_b).swap_dims(2, 3));
            m = m_new;
            l = l.mul(alpha).add(e_sum);
        }

        let out = out.div(l).reshape([1, cfg.n_heads_q, 1, dh]);
        let [_, hq, _, dhh] = out.dims();
        out_proj.forward(out.swap_dims(1, 2).reshape([1, 1, hq * dhh]))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use burn::tensor::{Device, Distribution};

    fn device() -> Device {
        Device::ndarray()
    }

    fn msa() -> MsaModule {
        let cfg = MsaConfig {
            d_model: 32,
            n_heads_q: 4,
            n_heads_kv: 2,
            d_head: 8,
            d_idx: 16,
            block_size: 4,
            topk: 2,
            force_local_block: true,
            causal: true,
            use_kl_loss: false,
            gradient_detach: false,
            ..MsaConfig::default()
        };
        MsaModule::new(&cfg, &device())
    }

    fn maxdiff(a: &Tensor<3>, b: &Tensor<3>) -> f32 {
        let av: Vec<f32> = a.clone().into_data().to_vec().unwrap();
        let bv: Vec<f32> = b.clone().into_data().to_vec().unwrap();
        av.iter()
            .zip(&bv)
            .map(|(x, y)| (x - y).abs())
            .fold(0.0f32, f32::max)
    }

    /// Step-by-step cached attention equals the batched causal forward over
    /// the same sequence (random weights, local-block bias, topk < n_blocks
    /// and partial trailing blocks all exercised).
    ///
    /// The batched kernel's FINAL row of a partial trailing block clamps
    /// padding onto the last token and attends it several times (see
    /// `attend`); the cache gives clean prefix semantics instead, so for
    /// non-multiple lengths every row but that special final one is compared.
    #[test]
    fn cache_matches_batched_causal_forward() {
        let dev = device();
        let msa = msa();
        let bs = msa.cfg.block_size;
        for seq in [4usize, 8, 9, 13] {
            let x = Tensor::<3>::random([1, seq, 32], Distribution::Normal(0.0, 1.0), &dev);

            let reference = msa.forward::<burn_ndarray::NdArray>(x.clone()).output;

            let mut cache = MsaCache::new(msa.cfg.clone());
            cache.reset(1);
            let cached = cache.step(&msa, x, 0);

            // Compare row-slices [1, n_cmp, 32].
            let n_cmp = if seq % bs == 0 { seq } else { seq - 1 };
            let ref_rows = reference.slice([0..1, 0..n_cmp, 0..32]);
            let cached_rows = cached.slice([0..1, 0..n_cmp, 0..32]);
            let diff = maxdiff(&ref_rows, &cached_rows);
            assert!(
                diff < 1e-4,
                "seq {seq}: cached MSA diverged from batched on rows 0..{n_cmp}: {diff}"
            );
        }
    }

    /// Same inputs, same cache procedure twice: bitwise-identical outputs
    /// (block selection is deterministic, ties fall to the lowest block id).
    #[test]
    fn cache_selection_is_deterministic() {
        let dev = device();
        let msa = msa();
        let x = Tensor::<3>::random([1, 9, 32], Distribution::Normal(0.0, 1.0), &dev);
        let run = || {
            let mut c = MsaCache::new(msa.cfg.clone());
            c.reset(1);
            c.step(&msa, x.clone(), 0)
        };
        let (a, b) = (run(), run());
        let av: Vec<f32> = a.into_data().to_vec().unwrap();
        let bv: Vec<f32> = b.into_data().to_vec().unwrap();
        assert_eq!(av, bv, "block selection must be deterministic");
    }

    /// Stream memory grows O(S·d) — dims track pushed tokens exactly, mark/
    /// rollback truncate them back.
    #[test]
    fn cache_growth_is_linear_and_rollback_truncates() {
        let dev = device();
        let msa = msa();
        let mut cache = MsaCache::new(msa.cfg.clone());
        cache.reset(2);
        assert_eq!(cache.stream_len(0), 0);

        for t in 1..=7 {
            let xt = Tensor::<3>::random([1, 1, 32], Distribution::Normal(0.0, 1.0), &dev);
            cache.step(&msa, xt, 0);
            assert_eq!(cache.stream_len(0), t);
        }
        let stream = cache.iters[0].as_ref().unwrap();
        assert_eq!(stream.k.dims(), [1, 2, 7, 8]); // [1, Hkv, S, d_head]
        assert_eq!(stream.k_idx.dims(), [1, 1, 7, 16]);

        let mark = cache.mark();
        let xt = Tensor::<3>::random([1, 3, 32], Distribution::Normal(0.0, 1.0), &dev);
        cache.step(&msa, xt, 0);
        assert_eq!(cache.stream_len(0), 10);
        cache.rollback(&mark);
        assert_eq!(cache.stream_len(0), 7);
        cache.rollback(&mark); // idempotent at the mark
        assert_eq!(cache.stream_len(0), 7);
        assert_eq!(cache.stream_len(1), 0);
    }
}
